{
  "questions": [
    {
      "requirement_ids": ["r3"],
      "prompt": "Walk me through a time you had to diagnose a slow-running query in a high-traffic PostgreSQL database. What tools did you use to identify the bottleneck, and how did you verify that your optimization actually improved performance without introducing new locking issues?",
      "answer_outline": "A strong answer discusses using EXPLAIN ANALYZE, checking index usage, and identifying sequential scans. It should mention testing in a staging environment to avoid production locking issues and verifying the fix with metrics like query duration and buffer hits.",
      "difficulty": 3
    },
    {
      "requirement_ids": ["r2", "r4"],
      "prompt": "When designing a gRPC or REST API that will be consumed by multiple internal teams, how do you handle breaking changes? Describe your strategy for versioning and ensuring backward compatibility while keeping the codebase maintainable.",
      "answer_outline": "The candidate should discuss strategies like API versioning (URL vs headers), deprecation policies, and maintaining parallel versions. They should emphasize the importance of contract testing and clear documentation to minimize friction for consuming teams.",
      "difficulty": 2
    },
    {
      "requirement_ids": ["r1", "r9"],
      "prompt": "Describe a scenario where you implemented an event-driven architecture using Kafka or NATS. How did you handle event ordering, idempotency, and the potential for partial failures during message processing?",
      "answer_outline": "A good answer explains how they ensured message ordering (e.g., partition keys), implemented idempotency keys to handle retries safely, and used dead-letter queues or manual intervention strategies to manage failed events without blocking the pipeline.",
      "difficulty": 3
    },
    {
      "requirement_ids": ["r7"],
      "prompt": "How do you approach managing infrastructure changes for a production service using Terraform? Walk me through how you handle state management and ensure that a Terraform apply doesn't unexpectedly disrupt a running Kubernetes deployment.",
      "answer_outline": "The candidate should mention using remote state storage with locking, planning changes before applying, and using CI/CD pipelines to automate the process. They should also touch on testing changes in ephemeral environments or using canary deployments to mitigate risk.",
      "difficulty": 2
    },
    {
      "requirement_ids": ["r1", "r3"],
      "prompt": "In a system requiring high transactional correctness, such as a billing or scheduling service, how do you handle race conditions when two processes attempt to update the same record simultaneously in PostgreSQL?",
      "answer_outline": "The candidate should discuss using database-level locking mechanisms like SELECT FOR UPDATE, optimistic concurrency control with version columns, or appropriate transaction isolation levels. They should explain the trade-offs between these approaches regarding performance and data integrity.",
      "difficulty": 3
    }
  ]
}
